# Generated by make formula. Copy to jakemanger/homebrew-tap after release.
class Lsa < Formula
  desc "ls for agent sessions"
  homepage "https://github.com/jakemanger/lsa"
  url "https://github.com/jakemanger/lsa/releases/download/v0.1.3/lsa"
  version "0.1.3"
  sha256 "7d87ad11254d169494987959cdcde9b0d42b8dd85ec3b8e0c56eada911ea6daf"
  license "MIT"

  depends_on "jq"
  depends_on "sqlite"

  def install
    bin.install "lsa"
  end

  def caveats
    <<~'EOS'
      Oh My Zsh? Replace its default lsa='ls -lah' alias with the lsa command:
      printf '\nunalias lsa 2>/dev/null\n' >> ~/.zshrc && source ~/.zshrc
    EOS
  end

  test do
    assert_equal "lsa 0.1.3", shell_output("#{bin}/lsa --version").strip
    assert_match "ls for agent sessions", shell_output("#{bin}/lsa --help")
  end
end
